class ReservationPolicy(TypedDict):
    """
    How the model gateway keeps a run inside its cost cap. `worst_case`: before each upstream
    call, the call reserves its worst-case cost (its request and its completion ceiling at the
    prices of its policy); a call that cannot fit is refused and never goes upstream. `none`: the
    gateway counts the cost after each call only.
    """
    policy: Literal["worst_case", "none"]
    #: The fraction of the cost cap after which no new work starts; the running work finishes in the
    #: rest.
    softStopFraction: NotRequired[float]
    #: How long a call that fits only after the calls in flight settle waits for them.
    holdWaitSeconds: NotRequired[int]


class Budget(TypedDict):
    """
    The limits of one run of model work. The first limit that the run reaches ends it. Money is
    an integer count of millionths of a US dollar, never a floating-point amount. An absent limit
    is no limit.
    """
    #: The cost cap of the model calls, in millionths of a US dollar (1000000 is 1 USD).
    costCapMicroUsd: NotRequired[int]
    #: The most tokens (input and output) that the run may use.
    tokenLimit: NotRequired[int]
    #: The longest time that the run may take.
    wallClockSeconds: NotRequired[int]
    #: The named depth that set the other limits, for example `quick`, `standard`, `deep` or `max`.
    depth: NotRequired[str]
    reservation: NotRequired[ReservationPolicy]


